"""Generate exact native cosmetic skeleton tracks, with no animation events."""
import json,hashlib
from pathlib import Path
from edge_data import poses
P=Path(__file__).resolve().parent;D=P/'item-mechanisms';lines=['#pragma once',
 '// Generated by build_crossbow_mechanism_data.py from exact-game Edge samples.',
 'struct CrossbowMechanismClip {unsigned joints,frames;const float (*qts)[7];};']
reports=[]
def values(v):return ','.join(format(float(x),'.9f')+'f'for x in v)
for role in ('corvo','emily'):
 D=P/('item-mechanisms-runtime-v2' if role=='corvo' else 'item-mechanisms')
 sk=json.loads((D/f'crossbow_{role}-skeleton.json').read_text());n=len(sk['joints'])
 lines.append(f'inline constexpr short crossbow_{role}_parents[]={{'+','.join(str(j['parent'])for j in sk['joints'])+'};')
 lines.append(f'inline constexpr float crossbow_{role}_bind[][7]={{'+','.join('{'+values(j['bindLocalQTS'][:7])+'}'for j in sk['joints'])+'};')
 for part in ('idle','fire','outofammo'):
  f=D/f'crossbow_{role}-crossbow_{part}.edgepose';meta=json.loads(f.with_suffix('.json').read_text());p=poses(f)
  assert p['sha256']==meta['sample_sha256']and p['joints']==n
  assert all(abs(q[k]-1)<1e-6 for frame in p['frames']for q in frame for k in range(8,11))
  name=f'crossbow_{role}_{part}';lines.append(f'inline constexpr float {name}_poses[][7]={{'+','.join('{'+values(q[:7])+'}'for frame in p['frames']for q in frame)+'};')
  lines.append(f'inline constexpr CrossbowMechanismClip {name}={{{n},{len(p["frames"])},{name}_poses}};')
  reports.append(dict(role=role,part=part,source=meta['asset'],source_sha256=meta['asset_sha256'],sample_sha256=p['sha256'],frames=len(p['frames']),joints=n))
lines.append('inline CrossbowMechanismClip crossbowMechanism(unsigned character,unsigned variant){return character==1?(variant==7?crossbow_corvo_fire:variant==2?crossbow_corvo_outofammo:crossbow_corvo_idle):(variant==7?crossbow_emily_fire:variant==2?crossbow_emily_outofammo:crossbow_emily_idle);}')
(P.parents[1]/'outputs/d2-coop-lab/src/crossbow_mechanism_data.h').write_text('\n'.join(lines)+'\n')
(P/'crossbow-mechanism-runtime-sources-v1.json').write_text(json.dumps(dict(events=False,source_executable='B671F8249422862BF557D00AAB2F4BB671ED4515CC10AD8A8A9DECAD84516180',clips=reports,fire_mechanism_ms=333,fire_arm_scene_ms=666),indent=2))
print('Generated six native mechanical clips; no events or actor-root motion')
